/* ---------- Chỉ đường ngay trên web (OSRM / OpenStreetMap, miễn phí, không cần khóa) ---------- */
const RT = {mode:'car', to:null, from:null, req:0};
const RT_URL = {car:'https://router.project-osrm.org/route/v1/driving/', foot:'https://routing.openstreetmap.de/routed-foot/route/v1/driving/', bike:'https://routing.openstreetmap.de/routed-bike/route/v1/driving/'};
function rtClear(){ ['rt-case', 'rt-line'].forEach(id => { if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', 'none'); }); RT.to = null; }
function rtStep(s){
  const M = {'left':'rẽ trái', 'right':'rẽ phải', 'slight left':'chếch sang trái', 'slight right':'chếch sang phải', 'sharp left':'quẹo gắt trái', 'sharp right':'quẹo gắt phải', 'straight':'đi thẳng', 'uturn':'quay đầu'};
  const m = s.maneuver || {}, t = m.type, md = M[m.modifier] || 'đi tiếp', nm = s.name ? ' vào <b>' + esc(s.name) + '</b>' : '';
  let txt;
  if (t === 'depart') txt = 'Xuất phát' + (s.name ? ' trên <b>' + esc(s.name) + '</b>' : '');
  else if (t === 'arrive') txt = 'Đến nơi';
  else if (t === 'roundabout' || t === 'rotary' || t === 'roundabout turn') txt = 'Vào vòng xoay, ra ở lối thứ ' + (m.exit || 1) + nm;
  else if (t === 'merge') txt = 'Nhập làn' + nm;
  else if (t === 'on ramp') txt = 'Vào đường nhánh' + nm;
  else if (t === 'off ramp') txt = 'Ra đường nhánh' + nm;
  else if (t === 'fork') txt = 'Tại ngã rẽ, ' + md + nm;
  else if (t === 'new name' || (t === 'continue' && m.modifier === 'straight')) txt = 'Đi tiếp' + nm;
  else txt = md.charAt(0).toUpperCase() + md.slice(1) + nm;
  return txt;
}
function rtKm(m){ return m >= 1000 ? (m / 1000).toLocaleString('vi-VN', {maximumFractionDigits:1}) + ' km' : Math.round(m / 10) * 10 + ' m'; }
function rtMin(s){ const m = Math.max(1, Math.round(s / 60)); return m >= 60 ? Math.floor(m / 60) + ' giờ ' + (m % 60) + ' phút' : m + ' phút'; }
function rtCard(html){
  geoEl.dataset.k = 'route'; geoEl.classList.remove('err'); geoEl.classList.add('gm');
  document.getElementById('geoT').textContent = 'Đường đi';
  document.getElementById('geoC').innerHTML = html;
  geoEl.hidden = false; document.getElementById('legend').classList.add('under');
  geoEl.querySelectorAll('[data-rm]').forEach(b => b.onclick = () => { RT.mode = b.dataset.rm; rtGo(); });
  const bk = document.getElementById('rtBack'); if (bk) bk.onclick = () => { rtClear(); if (PIN.ll) pinCard(); };
}
function rtTabs(){ return '<div class="gact rtm">' + [['car','🚗 Xe'],['bike','🚲 Xe đạp'],['foot','🚶 Đi bộ']].map(([k, t]) => '<button data-rm="' + k + '"' + (RT.mode === k ? ' class="pri"' : '') + '>' + t + '</button>').join('') + '</div>'; }
function rtGo(){
  const to = RT.to; if (!to) return;
  const id = ++RT.req;
  const run = from => {
    RT.from = from;
    rtCard(rtTabs() + '<div class="gsub">Đang tìm đường…</div>');
    fetch(RT_URL[RT.mode] + from[0] + ',' + from[1] + ';' + to[0] + ',' + to[1] + '?overview=full&geometries=geojson&steps=true')
      .then(r => r.json()).then(j => {
        if (id !== RT.req) return;
        const r = j.routes && j.routes[0]; if (!r) throw new Error(j.message || 'Không tìm được đường');
        const data = {type:'Feature', properties:{}, geometry:r.geometry};
        if (!map.getSource('rt')) { map.addSource('rt', {type:'geojson', data});
          map.addLayer({id:'rt-case', type:'line', source:'rt', layout:{'line-join':'round', 'line-cap':'round'}, paint:{'line-color':'#0d47a1', 'line-width':['interpolate', ['linear'], ['zoom'], 12, 6, 18, 12]}});
          map.addLayer({id:'rt-line', type:'line', source:'rt', layout:{'line-join':'round', 'line-cap':'round'}, paint:{'line-color':'#4c8bf5', 'line-width':['interpolate', ['linear'], ['zoom'], 12, 4, 18, 8]}}); }
        else map.getSource('rt').setData(data);
        ['rt-case', 'rt-line'].forEach(l => map.setLayoutProperty(l, 'visibility', 'visible'));
        const cs = r.geometry.coordinates, xs = cs.map(c => c[0]), ys = cs.map(c => c[1]);
        map.fitBounds([[Math.min(...xs), Math.min(...ys)], [Math.max(...xs), Math.max(...ys)]], {padding:mob() ? {top:130, bottom:Math.round(innerHeight * .5), left:30, right:60} : {top:90, bottom:60, left:420, right:500}, maxZoom:18, duration:900});
        const steps = (r.legs[0].steps || []).filter(s => s.distance > 0 || (s.maneuver && s.maneuver.type === 'arrive'));
        const g = 'https:' + '/' + '/' + 'www.google.com/maps/';
        rtCard(rtTabs() +
          '<div class="rtsum"><b>' + rtMin(r.duration) + '</b> <span>(' + rtKm(r.distance) + ')</span></div>' +
          '<div class="gsub">Từ vị trí của bạn tới ghim đỏ · đường theo bản đồ OpenStreetMap, chưa tính kẹt xe</div>' +
          '<div class="gact"><a class="pri" href="' + g + 'dir/?api=1&destination=' + to[1].toFixed(6) + ',' + to[0].toFixed(6) + '&dir_action=navigate" target="_blank" rel="noopener">▲ Dẫn đường bằng giọng nói</a><button id="rtBack">✕ Xóa tuyến</button></div>' +
          '<ol class="rtlist">' + steps.map(s => '<li><span>' + rtStep(s) + '</span><small>' + (s.distance > 0 ? rtKm(s.distance) : '') + '</small></li>').join('') + '</ol>');
      }).catch(e => { if (id !== RT.req) return; rtCard(rtTabs() + '<div class="gsub">Không tìm được đường: ' + esc(e.message || e) + '</div><div class="gact"><button id="rtBack">← Quay lại</button></div>'); });
  };
  if (LOC.last) run([LOC.last.coords.longitude, LOC.last.coords.latitude]);
  else if (RT.from && RT.from.fromGps) run(RT.from);
  else {
    rtCard(rtTabs() + '<div class="gsub">Đang lấy vị trí của bạn để làm điểm xuất phát…</div>');
    navigator.geolocation.getCurrentPosition(p => { if (id !== RT.req) return; const f = [p.coords.longitude, p.coords.latitude]; f.fromGps = 1; run(f); },
      () => { if (id !== RT.req) return; rtCard('<div class="gsub">Cần cho phép truy cập vị trí để chỉ đường từ chỗ bạn đang đứng. Hoặc bật nút định vị trước rồi bấm Đường đi.</div><div class="gact"><button id="rtBack">← Quay lại</button></div>'); },
      {enableHighAccuracy:GEO_HI, timeout:15000, maximumAge:30000});
  }
}
